    if(latest_bloom != "No Event"){
        // convert bloom from hexadecimal (API) to unsigned char and assign to bloom->bf
        convert_from_hexadecimal(&bloom, latest_bloom);
    }

    big ga_temp = mirvar(1);
    // check granted access history
