char *userTimerVerificationRequest( const std::vector<std::string> &Oi, const std::vector<std::string> &Ri, const char *SGAi)
{
    uid_t userid = getuid();
    int Ui = static_cast<int>(userid);
    //return value
    char *result = new char[1000];

    //start use MIRACL
    miracl *mip = mirsys(65535, 10);

    // get current Timestamp in UNIX format
    time_t t = time(NULL);
    char Ts[20];
    snprintf(Ts, sizeof(Ts), "%ld", t);

    std::cout << "Server Timestamp: " << Ts;

    //read user secret seed
    big secret_seed = read_secret(Ui);
    char Si[1000];
    cotstr(secret_seed, Si);

    //init bloom
    bloom_init(&bloom, bloom_entries, false_positive_rate);

    start2 = clock();
    // retrive the latest bloom filter
    std::string latest_bloom = getRequest();
    if(latest_bloom != "No Event"){
        // convert bloom from hexadecimal (API) to unsigned char and assign to bloom->bf
        convert_from_hexadecimal(&bloom, latest_bloom);
    }

    end2 = clock();

    big ga_temp = mirvar(1);
    // check granted access history
    char verif_file_temp[256];
    sprintf(verif_file_temp, "granted_access/%d/%s", Ui, SGAi);
    std::cout << "===============================================\n";
    FILE *file_temp = fopen(verif_file_temp, "r");
    cinnum(ga_temp, file_temp);

    fclose(file_temp);

    char ga_history[300];
    cotstr(ga_temp, ga_history);

    //compute VPs History to Check
    big check_vp = generateVerificationPoint(ga_history, Si);


    start = clock();

    if(!checkVerificationPoint(&bloom, check_vp)){
        snprintf(result, 100, "Access Denied");
        return result;
    }
    end = clock();

    cpu_time_used = ((double) (end2 - start2)) / CLOCKS_PER_SEC;
    printf("CPU time used for BF Fetching from Blockchain: %f seconds\n", cpu_time_used);

    double cpu_time_used_2, cpu_time_used_total;
    cpu_time_used_2 = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("CPU time used for VP Checking: %f seconds\n", cpu_time_used_2);

    cpu_time_used_total = cpu_time_used + cpu_time_used_2;
    printf("CPU time used for VP Verification: %f seconds\n", cpu_time_used_total);
    
    // Concatenate data
    char* data = new char[500];
    snprintf(data, 500, "%s", concatenateData(Ui, Oi, Ri, Ts));

    big res;
    res = mirvar(1);
    hashing(data, strlen(data), res);

    char GAij[300];
    // cotnum(res, stdout);

    cotstr(res, GAij);

    big VPij = generateVerificationPoint(GAij, Si);
    
    

    //save new verificationpoint
    char verif_file_path[256];
    sprintf(verif_file_path, "verification_point/verification_point_%d_%s.txt", Ui, Ts);
    FILE *verif_file = fopen(verif_file_path, "w");
    cotnum(VPij, verif_file);

    fclose(verif_file);

    addVerificationPoint(&bloom, VPij);

    //sent it to blockchain
    std::string params = (convert_to_hexadecimal(bloom.bf, bloom.bytes));
    postRequest(params);

    snprintf(result, 1000, "%s", GAij);
    
    return result;
}

char *userTimerStoringRequest( const std::vector<std::string> &Oi, const std::vector<std::string> &Ri, const char *SGAi)
{
    uid_t userid = getuid();
    int Ui = static_cast<int>(userid);
    //return value
    char *result = new char[1000];

    //start use MIRACL
    miracl *mip = mirsys(65535, 10);

    // get current Timestamp in UNIX format
    time_t t = time(NULL);
    char Ts[20];
    snprintf(Ts, sizeof(Ts), "%ld", t);

    std::cout << "Server Timestamp: " << Ts;

    //read user secret seed
    big secret_seed = read_secret(Ui);
    char Si[1000];
    cotstr(secret_seed, Si);

    //init bloom
    bloom_init(&bloom, bloom_entries, false_positive_rate);

    // retrive the latest bloom filter
    std::string latest_bloom = getRequest();
    if(latest_bloom != "No Event"){
        // convert bloom from hexadecimal (API) to unsigned char and assign to bloom->bf
        convert_from_hexadecimal(&bloom, latest_bloom);
    }


    big ga_temp = mirvar(1);
    // check granted access history
    char verif_file_temp[256];
    sprintf(verif_file_temp, "granted_access/%d/%s", Ui, SGAi);
    std::cout << "===============================================\n";
    FILE *file_temp = fopen(verif_file_temp, "r");
    cinnum(ga_temp, file_temp);

    fclose(file_temp);

    char ga_history[300];
    cotstr(ga_temp, ga_history);

    //compute VPs History to Check
    big check_vp = generateVerificationPoint(ga_history, Si);

    
    if(!checkVerificationPoint(&bloom, check_vp)){
        snprintf(result, 100, "Access Denied");
        return result;
    }

    
    // Concatenate data
    char* data = new char[500];
    snprintf(data, 500, "%s", concatenateData(Ui, Oi, Ri, Ts));

    big res;
    res = mirvar(1);
    hashing(data, strlen(data), res);

    char GAij[300];
    // cotnum(res, stdout);

    cotstr(res, GAij);

    big VPij = generateVerificationPoint(GAij, Si);

    start2 = clock();
    addVerificationPoint(&bloom, VPij);
    end2 = clock();

    start = clock();
    // sent it to blockchain
    std::string params = (convert_to_hexadecimal(bloom.bf, bloom.bytes));
    postRequest(params);

    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;
    printf("CPU time used for Storing: %f seconds\n", cpu_time_used);
    cpu_time_used = ((double)(end2 - start2)) / CLOCKS_PER_SEC;
    printf("CPU time used for Insertion: %f seconds\n", cpu_time_used);

    snprintf(result, 1000, "%s", GAij);

    //save new verificationpoint
    char verif_file_path[256];
    sprintf(verif_file_path, "verification_point/verification_point_%d_%s.txt", Ui, Ts);
    FILE *verif_file = fopen(verif_file_path, "w");
    cotnum(VPij, verif_file);

    fclose(verif_file);

    return result;
}
